parameters.functionCode:
const projectId = $json.projectId;
const expertName = $json.expertName;
const markdownContent = $json.markdownContent;
const fileName = $json.fileName || `${expertName}-analysis-${Date.now()}.md`;

return {
  json: {
    projectId,
    expertName,
    markdownContent,
    fileName
  }
};

const githubRepoUrl = $json.github_repo_url;
const extractData = $('Extract Inputs').first().json;
const fileName = extractData.fileName;
const markdownContent = extractData.markdownContent;

// Extract org and repo from URL
const repoMatch = githubRepoUrl.match(/github\.com[/:]([^/]+)\/([^/.]+)/);
const githubOrg = repoMatch ? repoMatch[1] : 'shlapolosa';
const githubRepo = repoMatch ? repoMatch[2] : 'default-repo';

// Get GitHub token from environment
const githubToken = process.env.GITHUB_TOKEN || '';

// Base64 encode content
const contentBase64 = Buffer.from(markdownContent).toString('base64');

const filePath = `docs/analysis/${fileName}`;

return {
  json: {
    githubOrg,
    githubRepo,
    githubToken,
    filePath,
    contentBase64,
    fileName
  }
};

const response = $json;
const prepareData = $('Prepare GitHub API').first().json;
const filePath = prepareData.filePath;
const contentBase64 = prepareData.contentBase64;
const githubOrg = prepareData.githubOrg;
const githubRepo = prepareData.githubRepo;
const githubToken = prepareData.githubToken;
const fileName = prepareData.fileName;

let sha = null;
if (response && response.sha) {
  sha = response.sha; // File exists, get its SHA for update
}

return {
  json: {
    githubOrg,
    githubRepo,
    githubToken,
    filePath,
    contentBase64,
    fileName,
    sha,
    isUpdate: sha !== null
  }
};

