parameters.functionCode:
const response = $json;
const shaData = $('Get SHA if Exists').first().json;
const fileName = shaData.fileName;
const githubOrg = shaData.githubOrg;
const githubRepo = shaData.githubRepo;
const filePath = shaData.filePath;

const fileUrl = `https://github.com/${githubOrg}/${githubRepo}/blob/main/${filePath}`;

return {
  json: {
    success: true,
    fileName,
    fileUrl,
    htmlUrl: response.content ? response.content.html_url : fileUrl
  }
};
